"use client";

import { useEffect, useRef, useState } from "react";
import type { CSSProperties, RefObject } from "react";

import { PET_MANIFEST } from "@/lib/pet-manifest";
import {
  createPetState,
  defaultIdleAction,
  DEFAULT_PET_BEHAVIOR,
  resolveAction,
  stepPet,
} from "@/lib/web-pet-engine";
import type { PetBehavior, PetMode, PetState } from "@/lib/web-pet-engine";

export type { PetBehavior, PetIdleAction, PetMovementAction } from "@/lib/web-pet-engine";

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export type WebPetProps = {
  /** Folder name under `mediaBaseUrl`, e.g. "dog". */
  animal: string;
  /** Color variant, e.g. "brown". Defaults to the animal's first color. */
  color?: string;
  /** `fixed` roams the viewport; `absolute` roams its offset parent. */
  position?: "fixed" | "absolute";
  /** Base movement speed in px per tick. Defaults to the animal's tuned speed. */
  speed?: number;
  /** Render scale of the 100x100 GIF. */
  scale?: number;
  /** Chase the cursor instead of wandering. */
  followMouse?: boolean;
  /** Text shown in a speech bubble while the cursor is near the pet. */
  hoverMessage?: string;
  zIndex?: number;
  style?: CSSProperties;
  /** Where the GIFs are served from. Defaults to "/media". */
  mediaBaseUrl?: string;
  /** Fine-grained behavior knobs; anything omitted uses sensible defaults. */
  behavior?: Partial<
    Pick<
      PetBehavior,
      | "idleDist"
      | "hoverAction"
      | "hoverDist"
      | "idlePauseMs"
      | "actions"
      | "idleActions"
      | "movementActions"
    >
  >;
  speech?: {
    maxWidth?: number;
    offsetY?: number;
  };
};

/** Base speed for an animal, from the generated manifest. */
export function getWebPetSpeed(animal: string, fallback = DEFAULT_PET_BEHAVIOR.speed) {
  return PET_MANIFEST[animal]?.speed ?? fallback;
}

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

type WebPetConfig = {
  behavior: PetBehavior;
  gifUrl: (action: string) => string;
  scale: number;
};

const SPRITE_SIZE_PX = 100;
const TICK_MS = 125;
const BUBBLE_GAP_PX = 6;
const DEFAULT_SCALE = 0.5;
const DEFAULT_Z_INDEX = 9999;
const DEFAULT_MEDIA_BASE_URL = "/media";
const DEFAULT_SPEECH = { maxWidth: 160, offsetY: 0 };

function resolveConfig(props: WebPetProps): WebPetConfig {
  const manifest = PET_MANIFEST[props.animal];
  const overrides = props.behavior ?? {};
  const colors = manifest?.colors ?? [];
  // Unknown colors fall back to a real one so we never request a missing GIF.
  const color =
    props.color && (colors.length === 0 || colors.includes(props.color))
      ? props.color
      : (colors[0] ?? "brown");
  const base = (props.mediaBaseUrl ?? DEFAULT_MEDIA_BASE_URL).replace(/\/$/, "");

  const behavior: PetBehavior = {
    ...DEFAULT_PET_BEHAVIOR,
    ...overrides,
    actions: overrides.actions ?? manifest?.actions ?? DEFAULT_PET_BEHAVIOR.actions,
    speed: props.speed ?? manifest?.speed ?? DEFAULT_PET_BEHAVIOR.speed,
    followMouse: props.followMouse ?? DEFAULT_PET_BEHAVIOR.followMouse,
  };

  return {
    behavior,
    scale: props.scale ?? DEFAULT_SCALE,
    gifUrl: (action) =>
      `${base}/${props.animal}/${color}_${resolveAction(behavior, action)}_8fps.gif`,
  };
}

// ---------------------------------------------------------------------------
// Shared cursor tracking (one listener for every pet on the page)
// ---------------------------------------------------------------------------

const cursor = { x: 0, y: 0, known: false };
let cursorSubscribers = 0;

function onPointerMove(event: PointerEvent) {
  cursor.x = event.clientX;
  cursor.y = event.clientY;
  cursor.known = true;
}

function subscribeCursor(): () => void {
  if (cursorSubscribers === 0) {
    document.addEventListener("pointermove", onPointerMove, { passive: true });
  }
  cursorSubscribers += 1;
  return () => {
    cursorSubscribers -= 1;
    if (cursorSubscribers === 0) {
      document.removeEventListener("pointermove", onPointerMove);
    }
  };
}

// ---------------------------------------------------------------------------
// Animation loop: reads the world, steps the engine, paints the DOM
// ---------------------------------------------------------------------------

type Bounds = { left: number; bottom: number; width: number };

/**
 * The box the pet roams in. Derived from where the wrapper actually landed,
 * because `position: fixed` gets re-parented by any ancestor with a transform,
 * filter, or backdrop-filter (a blurred sticky header, for example).
 */
function readBounds(wrapper: HTMLElement, position: "fixed" | "absolute"): Bounds {
  const rect = wrapper.getBoundingClientRect();
  const left = rect.left - (parseFloat(wrapper.style.left) || 0);
  const bottom = rect.bottom;

  const atViewportBottom = Math.abs(bottom - window.innerHeight) < 1;
  const container =
    position === "absolute"
      ? (wrapper.offsetParent ?? wrapper.parentElement)
      : atViewportBottom
        ? null
        : wrapper.parentElement;

  const width = container
    ? container.getBoundingClientRect().width
    : window.innerWidth;

  return { left, bottom, width };
}

function paint(
  wrapper: HTMLElement,
  sprite: HTMLElement,
  state: PetState,
  config: WebPetConfig,
  painted: { src: string | null; facing: number | null },
) {
  const width = SPRITE_SIZE_PX * config.scale;
  wrapper.style.left = `${state.x - width / 2}px`;

  const src = config.gifUrl(state.action);
  if (painted.src !== src) {
    painted.src = src;
    sprite.style.backgroundImage = `url("${src}")`;
  }
  if (painted.facing !== state.facing) {
    painted.facing = state.facing;
    sprite.style.transform = `scaleX(${state.facing})`;
  }
}

function useWebPetLoop(
  wrapperRef: RefObject<HTMLDivElement | null>,
  spriteRef: RefObject<HTMLDivElement | null>,
  config: WebPetConfig,
  position: "fixed" | "absolute",
  onModeChange: (mode: PetMode) => void,
) {
  // The loop reads the latest config each tick, so prop changes never restart it.
  const configRef = useRef(config);
  const positionRef = useRef(position);
  useEffect(() => {
    configRef.current = config;
    positionRef.current = position;
  });

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const sprite = spriteRef.current;
    if (!wrapper || !sprite) return;

    let state = createPetState(configRef.current.behavior);
    const painted = { src: null as string | null, facing: null as number | null };
    let lastMode: PetMode | null = null;
    let lastTick = 0;
    let frame: number | null = null;

    const tick = (ts: number) => {
      frame = requestAnimationFrame(tick);
      if (ts - lastTick < TICK_MS) return;
      lastTick = ts;

      const current = configRef.current;
      const bounds = readBounds(wrapper, positionRef.current);
      const size = SPRITE_SIZE_PX * current.scale;

      state = stepPet(
        state,
        {
          ts,
          boundsWidth: bounds.width,
          mouse: cursor.known
            ? { x: cursor.x - bounds.left, y: cursor.y - bounds.bottom }
            : null,
          sprite: { width: size, height: size },
        },
        current.behavior,
      );

      paint(wrapper, sprite, state, current, painted);
      if (state.mode !== lastMode) {
        lastMode = state.mode;
        onModeChange(state.mode);
      }
    };

    paint(wrapper, sprite, state, configRef.current, painted);

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reducedMotion) return;

    const unsubscribe = subscribeCursor();
    frame = requestAnimationFrame(tick);

    return () => {
      unsubscribe();
      if (frame !== null) cancelAnimationFrame(frame);
    };
  }, [wrapperRef, spriteRef, onModeChange]);
}

// ---------------------------------------------------------------------------
// Speech bubble anchoring: find where the sprite's head is
// ---------------------------------------------------------------------------

/** Fraction of the GIF height that is transparent above the sprite, per URL. */
const headPaddingCache = new Map<string, Promise<number | null>>();

function measureHeadPadding(src: string): Promise<number | null> {
  const cached = headPaddingCache.get(src);
  if (cached) return cached;

  const promise = new Promise<number | null>((resolve) => {
    const image = new Image();
    image.onload = () => {
      try {
        const canvas = document.createElement("canvas");
        canvas.width = image.naturalWidth;
        canvas.height = image.naturalHeight;
        const ctx = canvas.getContext("2d");
        if (!ctx || canvas.height === 0) return resolve(null);
        ctx.drawImage(image, 0, 0);
        const { data, width, height } = ctx.getImageData(0, 0, canvas.width, canvas.height);
        for (let y = 0; y < height; y += 1) {
          for (let x = 0; x < width; x += 1) {
            if (data[(y * width + x) * 4 + 3] > 10) return resolve(y / height);
          }
        }
        resolve(0);
      } catch {
        resolve(null);
      }
    };
    image.onerror = () => resolve(null);
    image.src = src;
  });

  headPaddingCache.set(src, promise);
  return promise;
}

function useBubbleAnchor(src: string, spriteHeight: number): number | undefined {
  const [padding, setPadding] = useState<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    measureHeadPadding(src).then((value) => {
      if (!cancelled) setPadding(value);
    });
    return () => {
      cancelled = true;
    };
  }, [src]);

  if (padding === null) return undefined;
  return Math.round(spriteHeight * (1 - padding) + BUBBLE_GAP_PX);
}

// ---------------------------------------------------------------------------
// Presentation
// ---------------------------------------------------------------------------

type SpeechBubbleProps = {
  text: string;
  maxWidth: number;
  offsetY: number;
  anchorBottomPx?: number;
};

function SpeechBubble({ text, maxWidth, offsetY, anchorBottomPx }: SpeechBubbleProps) {
  const tail: CSSProperties = {
    position: "absolute",
    top: "100%",
    left: "50%",
    width: 0,
    height: 0,
  };

  return (
    <div
      role="status"
      style={{
        position: "absolute",
        left: "50%",
        bottom: anchorBottomPx !== undefined ? `${anchorBottomPx}px` : "100%",
        transform: `translate(-50%, ${offsetY}px)`,
        padding: "6px 8px",
        maxWidth: `${maxWidth}px`,
        borderRadius: "var(--radius, 8px)",
        border: "1px solid var(--border, #d4d4d8)",
        background: "var(--popover, #fff)",
        color: "var(--popover-foreground, #18181b)",
        fontFamily: "var(--font-pixel, inherit)",
        fontSize: "12px",
        lineHeight: 1.2,
        textAlign: "center",
        boxShadow: "var(--shadow-sm, 0 1px 3px rgba(0,0,0,0.15))",
        pointerEvents: "none",
        zIndex: 1,
      }}
    >
      {text}
      <div
        aria-hidden
        style={{
          ...tail,
          transform: "translateX(-50%)",
          borderLeft: "7px solid transparent",
          borderRight: "7px solid transparent",
          borderTop: "7px solid var(--border, #d4d4d8)",
        }}
      />
      <div
        aria-hidden
        style={{
          ...tail,
          transform: "translateX(-50%) translateY(-1px)",
          borderLeft: "6px solid transparent",
          borderRight: "6px solid transparent",
          borderTop: "6px solid var(--popover, #fff)",
        }}
      />
    </div>
  );
}

export function WebPet(props: WebPetProps) {
  const {
    position = "fixed",
    zIndex = DEFAULT_Z_INDEX,
    style,
    hoverMessage,
    speech,
  } = props;

  const wrapperRef = useRef<HTMLDivElement | null>(null);
  const spriteRef = useRef<HTMLDivElement | null>(null);
  const [mode, setMode] = useState<PetMode>("idle");

  // Cheap to rebuild every render; the loop reads it through a ref, so
  // identity changes never restart the animation.
  const config = resolveConfig(props);

  const sizePx = SPRITE_SIZE_PX * config.scale;
  const idleGif = config.gifUrl(defaultIdleAction(config.behavior));
  const hoverGif = config.gifUrl(config.behavior.hoverAction);

  useWebPetLoop(wrapperRef, spriteRef, config, position, setMode);
  const bubbleAnchor = useBubbleAnchor(hoverGif, sizePx);

  const message = hoverMessage?.trim() ?? "";
  const showBubble = mode === "hover" && message.length > 0;

  return (
    <div
      ref={wrapperRef}
      style={{
        position,
        bottom: 0,
        left: 0,
        height: `${sizePx}px`,
        width: `${sizePx}px`,
        zIndex,
        pointerEvents: "none",
        ...style,
      }}
    >
      {showBubble ? (
        <SpeechBubble
          text={message}
          maxWidth={speech?.maxWidth ?? DEFAULT_SPEECH.maxWidth}
          offsetY={speech?.offsetY ?? DEFAULT_SPEECH.offsetY}
          anchorBottomPx={bubbleAnchor}
        />
      ) : null}
      <div
        ref={spriteRef}
        style={{
          height: "100%",
          width: "100%",
          backgroundImage: `url("${idleGif}")`,
          backgroundRepeat: "no-repeat",
          backgroundPosition: "bottom center",
          backgroundSize: "contain",
          imageRendering: "pixelated",
          transformOrigin: "bottom center",
          pointerEvents: "none",
        }}
      />
    </div>
  );
}

/**
 * Pure simulation for a web pet. No React, no DOM.
 *
 * `stepPet` takes the previous state plus what the world looks like right now
 * and returns the next state. The component is responsible for feeding it
 * inputs and painting the result.
 */

export type PetIdleAction = {
  name: string;
  /** Base duration in ms. */
  baseDuration: number;
  /** Random extra duration in ms added on top of baseDuration. */
  extraDuration: number;
};

export type PetMovementAction = {
  name: string;
  /** Multiplier applied to the base speed. */
  speedMultiplier: number;
};

export type PetBehavior = {
  /** Base movement speed in px per tick. */
  speed: number;
  /** If true the pet chases the cursor; otherwise it wanders. */
  followMouse: boolean;
  /** Distance (px) from the target at which the pet stops and idles. */
  idleDist: number;
  /** Action shown while the cursor is within `hoverDist` of the sprite. */
  hoverAction: string;
  /** Distance (px) from the sprite center at which hover triggers. */
  hoverDist: number;
  /** Random pause (ms) between wander segments. */
  idlePauseMs: { min: number; max: number };
  /** Actions this pet has GIFs for. Unknown actions fall back to the first. */
  actions: string[];
  idleActions: PetIdleAction[];
  movementActions: PetMovementAction[];
};

export type PetMode = "hover" | "idle" | "walking";

export type PetState = {
  /** Horizontal center of the sprite, in px from the left of its bounds. */
  x: number;
  facing: 1 | -1;
  mode: PetMode;
  /** Action whose GIF should be displayed. */
  action: string;
  idleAction: string;
  idleActionUntil: number;
  idleCooldownUntil: number;
  movementAction: string;
  movementSpeedMultiplier: number;
  /** Wander destination, or null when a new one should be picked. */
  targetX: number | null;
  pauseUntil: number;
};

export type PetInput = {
  /** Timestamp in ms (e.g. from requestAnimationFrame). */
  ts: number;
  /** Width of the area the pet may roam, in px. */
  boundsWidth: number;
  /**
   * Cursor position relative to the bottom-left corner of the pet's bounds,
   * with y growing downward (so a cursor above the floor has negative y).
   * Null when the cursor position is unknown.
   */
  mouse: { x: number; y: number } | null;
  /** Rendered sprite size in px. */
  sprite: { width: number; height: number };
};

export const EDGE_MARGIN_PX = 16;
const WANDER_MIN_RATIO = 0.2;
const WANDER_MAX_RATIO = 0.55;

export const DEFAULT_PET_BEHAVIOR: PetBehavior = {
  speed: 4.5,
  followMouse: false,
  idleDist: 48,
  hoverAction: "swipe",
  hoverDist: 50,
  idlePauseMs: { min: 1500, max: 2200 },
  actions: ["idle", "run", "swipe", "walk", "walk_fast", "with_ball"],
  idleActions: [
    { name: "idle", baseDuration: 2500, extraDuration: 2000 },
    { name: "swipe", baseDuration: 1200, extraDuration: 800 },
  ],
  movementActions: [
    { name: "walk", speedMultiplier: 1.0 },
    { name: "walk_fast", speedMultiplier: 1.35 },
    { name: "run", speedMultiplier: 1.8 },
  ],
};

export function resolveAction(behavior: PetBehavior, action: string): string {
  if (behavior.actions.includes(action)) return action;
  return behavior.actions[0] ?? action;
}

export function defaultIdleAction(behavior: PetBehavior): string {
  return resolveAction(behavior, behavior.idleActions[0]?.name ?? "idle");
}

export function createPetState(
  behavior: PetBehavior,
  initialX = EDGE_MARGIN_PX,
): PetState {
  const idle = defaultIdleAction(behavior);
  return {
    x: initialX,
    facing: 1,
    mode: "idle",
    action: idle,
    idleAction: idle,
    idleActionUntil: 0,
    idleCooldownUntil: 0,
    movementAction: behavior.movementActions[0]?.name ?? "walk",
    movementSpeedMultiplier: behavior.movementActions[0]?.speedMultiplier ?? 1,
    targetX: null,
    pauseUntil: 0,
  };
}

function clampX(x: number, boundsWidth: number): number {
  const max = Math.max(EDGE_MARGIN_PX, boundsWidth - EDGE_MARGIN_PX);
  return Math.min(max, Math.max(EDGE_MARGIN_PX, x));
}

function pickWanderTarget(
  x: number,
  boundsWidth: number,
  random: () => number,
): number {
  const maxX = Math.max(EDGE_MARGIN_PX, boundsWidth - EDGE_MARGIN_PX);
  const roomLeft = Math.max(0, x - EDGE_MARGIN_PX);
  const roomRight = Math.max(0, maxX - x);
  const minDist = boundsWidth * WANDER_MIN_RATIO;
  const maxDist = boundsWidth * WANDER_MAX_RATIO;
  const dist = minDist + random() * Math.max(0, maxDist - minDist);

  const canLeft = roomLeft >= dist;
  const canRight = roomRight >= dist;
  let dir: 1 | -1;
  if (canLeft && canRight) dir = random() < 0.5 ? -1 : 1;
  else if (canLeft) dir = -1;
  else if (canRight) dir = 1;
  else dir = roomLeft > roomRight ? -1 : 1;

  return clampX(x + dir * dist, boundsWidth);
}

function pickMovement(
  behavior: PetBehavior,
  random: () => number,
): Pick<PetState, "movementAction" | "movementSpeedMultiplier"> {
  const options = behavior.movementActions;
  const choice = options[Math.floor(random() * options.length)];
  return {
    movementAction: choice?.name ?? "walk",
    movementSpeedMultiplier: choice?.speedMultiplier ?? 1,
  };
}

function pickIdle(
  behavior: PetBehavior,
  ts: number,
  random: () => number,
): Pick<PetState, "idleAction" | "idleActionUntil" | "idleCooldownUntil"> | null {
  const options = behavior.idleActions;
  const choice = options[Math.floor(random() * options.length)];
  if (!choice) return null;
  const until = ts + choice.baseDuration + random() * choice.extraDuration;
  return {
    idleAction: choice.name,
    idleActionUntil: until,
    idleCooldownUntil: until + behavior.idlePauseMs.min / 8,
  };
}

function schedulePause(
  behavior: PetBehavior,
  ts: number,
  random: () => number,
): number {
  const { min, max } = behavior.idlePauseMs;
  return ts + min + random() * Math.max(0, max - min);
}

function isHovered(state: PetState, input: PetInput, behavior: PetBehavior) {
  if (!input.mouse) return false;
  const centerX = state.x;
  const centerY = -input.sprite.height / 2; // sprite sits on the bottom edge
  const dist = Math.hypot(input.mouse.x - centerX, input.mouse.y - centerY);
  return dist <= behavior.hoverDist;
}

/**
 * Advance the pet by one tick.
 *
 * `random` is injectable so the machine can be driven deterministically.
 */
export function stepPet(
  prev: PetState,
  input: PetInput,
  behavior: PetBehavior,
  random: () => number = Math.random,
): PetState {
  const { ts, boundsWidth } = input;
  const next: PetState = { ...prev };

  // 1. Where are we heading?
  let targetX: number;
  if (behavior.followMouse) {
    targetX = input.mouse?.x ?? next.x;
    next.targetX = null;
  } else if (ts < next.pauseUntil) {
    targetX = next.x;
  } else {
    if (next.targetX === null) {
      Object.assign(next, pickMovement(behavior, random));
      next.targetX = pickWanderTarget(next.x, boundsWidth, random);
    }
    targetX = next.targetX;
  }

  const diffX = targetX - next.x;
  const distX = Math.abs(diffX);
  if (distX > 0.5) next.facing = diffX < 0 ? -1 : 1;

  const arrived = distX < behavior.idleDist;
  if (arrived && next.targetX !== null) {
    next.targetX = null;
    next.pauseUntil = schedulePause(behavior, ts, random);
  }

  // 2. Which mode are we in?
  if (isHovered(next, input, behavior)) {
    next.mode = "hover";
    next.action = resolveAction(behavior, behavior.hoverAction);
    return next;
  }

  if (arrived) {
    next.mode = "idle";
    if (ts > next.idleCooldownUntil && ts > next.idleActionUntil) {
      Object.assign(next, pickIdle(behavior, ts, random) ?? {});
    }
    next.action = resolveAction(behavior, next.idleAction);
    return next;
  }

  // 3. Walking.
  next.mode = "walking";
  const step = behavior.speed * next.movementSpeedMultiplier;
  next.x = clampX(next.x + Math.sign(diffX) * Math.min(step, distX), boundsWidth);
  next.idleAction = defaultIdleAction(behavior);
  next.idleActionUntil = 0;
  next.idleCooldownUntil = 0;
  next.action = resolveAction(behavior, next.movementAction);
  return next;
}
